package dev.zomboidmelee.boxing;
import java.util.*;import dev.zomboidmelee.boxing.CombatChecks18.*;import dev.zomboidmelee.boxing.Checks16.Stack;import net.minecraft.client.Minecraft;import net.neoforged.neoforge.network.PacketDistributor;
public class ActionChecks20{
 static int checks;static void ok(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
 public static class InvulZombie extends Zombie{public float last=1;public InvulZombie(Level w){super(w);}public boolean hurt(Object source,float amount){if(invulnerableTime>10&&amount<=last)return false;last=amount;invulnerableTime=20;return super.hurt(source,amount);}}public static class ChestMenu{}public static class Tick{Object p;Tick(Object p){this.p=p;}public Object getEntity(){return p;}}
 public static class Source{Object p;Source(Object p){this.p=p;}public Object getEntity(){return p;}public Object getDirectEntity(){return p;}public String getMsgId(){return "player";}}
 public static class Damage{Object v,p;float damage;Damage(Object v,Object p,float d){this.v=v;this.p=p;damage=d;}public Object getEntity(){return v;}public Source getSource(){return new Source(p);}public float getNewDamage(){return damage;}}
 public static void main(String[]args){Actor immunePlayer=new Actor();InvulZombie immune=new InvulZombie(immunePlayer.w);immune.invulnerableTime=12;ok(!immune.hurt(immunePlayer,1),"vanilla equal-damage hit is rejected inside the remaining immunity window");ok(Server20.vanilla(immunePlayer,immune)&&immune.hurt(immunePlayer,1),"accepted v20 strike actually deals equal damage inside the former 8/10-tick gap");Actor p=new Actor();Zombie z=new Zombie(p.w);p.w.entities.put(1,z);
  z.invulnerableTime=12;ok(z.invulnerableTime>10,"v19 eight-tick repeated strike is still inside vanilla immunity");ok(Server20.vanilla(p,z)&&z.invulnerableTime==10,"accepted light attack clears only conflicting immunity window");ok(!Server20.vanilla(p,z),"same-tick spam rejected");p.w.time+=8;z.invulnerableTime=12;ok(Server20.vanilla(p,z)&&z.invulnerableTime==10,"second same-strength hit can register after eight ticks");
  int sounds=p.w.sounds;Server20.hit(new Damage(z,p,1));ok(p.w.sounds==sounds+1,"light contact has world sound");ok(((Heavy18)PacketDistributor.cues.get(PacketDistributor.cues.size()-1)).action()==16,"only actual damage confirms light impact");sounds=p.w.sounds;Server20.hit(new Damage(z,p,0));ok(p.w.sounds==sounds,"zero damage is not presented as a hit");
  p.w.time+=20;Combat18.heavy(p,1);ok(Combat18.NEXT.get(p)==p.w.time+18,"heavy shared cooldown preserved");ok(z.damage==3,"heavy server damage");ok(z.dy==0,"momentum never adds an upward impulse");
  z.state=1<<30;z.alive=true;p.w.time+=30;p.look=new net.minecraft.world.phys.Vec3(0,-1.2,2);double len=Math.hypot(1.2,2);p.look=p.look.scale(1/len);ok(Stomp18.stompAim(p,z),"fallen torso is valid stomp target");ok(!Stomp18.headAim(p,z),"torso ray is not misclassified as a precision head hit");Stomp18.stomp(p,1);ok(z.damage==10&&z.alive,"body stomp works without headshot or random gate");
  p.w.time+=20;z.alive=true;p.look=new net.minecraft.world.phys.Vec3(0,-1.25,1.05).scale(1/Math.hypot(1.25,1.05));Stomp18.stomp(p,1);ok(!z.alive&&(z.state&1)!=0,"head stomp remains lethal with head burst");
  int cues=PacketDistributor.cues.size();p.containerMenu=new ChestMenu();Server20.tick(new Tick(p));Server20.tick(new Tick(p));ok(PacketDistributor.cues.size()==cues+1&&((Heavy18)PacketDistributor.cues.get(cues)).action()==14,"search cue once on chest open");p.containerMenu=p.inventoryMenu;Server20.tick(new Tick(p));ok(((Heavy18)PacketDistributor.cues.get(cues+1)).action()==15,"search stops on close");
  for(int kind=0;kind<4;kind++)for(int i=0;i<=100;i++){double phase=i/100.0;Motion20.Frame f=Motion20.arm(kind,0,0,phase);ok(Double.isFinite(f.x()+f.y()+f.z()+f.rx()+f.ry()+f.rz()),"finite animation sample");}
  Motion20.Frame jab=Motion20.arm(0,0,0,.30),hook=Motion20.arm(1,0,0,.46);ok(Math.abs(jab.x()-hook.x())>.15&&Math.abs(jab.ry()-hook.ry())>20,"heavy lateral hook is not a scaled jab");Motion20.Frame lift=Motion20.leg(.32),impact=Motion20.leg(.55);ok(lift.y()-impact.y()>.4&&Math.abs(lift.z()-impact.z())<.15,"stomp moves down rather than kicking forward");ok(Motion20.camera(.5)==0,"impact camera completely settles");
  Minecraft mc=Minecraft.INSTANCE;mc.player=p;mc.level=p.w;p.w.entities.put(50,p);final long[]now={1_000_000_000L};BoxingClient16.CLOCK=()->now[0];Client20.begin(p,1,false);Client20.receive(50,11);ok(Client20.kind(p)==1,"server and client agree on heavy type");now[0]+=100_000_000L;Client20.receive(50,17);now[0]+=200_000_000L;Camera camera=new Camera();Client20.camera(camera);ok(camera.pitch!=10,"heavy camera has predicted movement and confirmed impact");p.w.time+=20;p.main=new Stack(false);Shove20.recoil(z,.4,0,-1);ok(z.dy==0&&z.dz>0,"V recoil is horizontal");p.main=new Stack(true);
  int soundCount=p.localSounds;now[0]+=2_000_000_000L;Client20.begin(p,0,false);Client20.begin(p,0,false);ok(p.localSounds==soundCount+1,"air jab whoosh audible once, no raw/logical click double sound");
  var model=new Checks16.ShadowModel();Render20.pose(model,0,-1,.2f,.1f);ok(((net.minecraft.client.model.HumanoidModel<?>)model).rightArm.xRot==-1,"typed arm access bypasses GeoBone shadow");System.out.println("ACTION20_DAMAGE_SOUND_STOMP_SEARCH_CAMERA_TYPED_ARMS_CHECKS="+checks);
 }
}
